steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams {
          nodes {
            id
            name
            issues(filter: { state: { not: { deleted: true } } }) {
              nodes {
                id
                identifier
                title
                priority
                createdAt
                creator {
                  name
                }
              }
            }
          }
        }
      }
    }
  }'
